<?php
namespace App;use Illuminate\Database\Eloquent\Model;
class PaymentMethod extends Model{protected $guarded=[];protected $hidden=['credentials'];protected $casts=['supports_emi'=>'boolean','is_active'=>'boolean','show_at_checkout'=>'boolean','allow_sandbox_at_checkout'=>'boolean','charge_enabled'=>'boolean','display_charge_at_checkout'=>'boolean','require_transaction_id'=>'boolean','require_sender_number'=>'boolean','require_payment_screenshot'=>'boolean','is_archived'=>'boolean','availability_rules'=>'array','available_from'=>'datetime','available_until'=>'datetime','credentials_updated_at'=>'datetime','last_connection_test_at'=>'datetime'];public function emiPlans(){return $this->hasMany(EmiPlan::class)->where('is_active',1)->orderBy('months');}public function transactions(){return $this->hasMany(PaymentTransaction::class);}public function publicName(){return $this->customer_label?:$this->name;}public function isOnline(){return in_array($this->integration_mode,['api','redirect','hosted_checkout'],true);}public function requiresManualVerification(){return $this->payment_verification_mode==='manual'||$this->integration_mode==='manual';}}
